from collections import deque

class WorkQueue:
    def __init__(self):
        self.pending = deque()
        self.finished = []

    def add(self, item):
        self.pending.append(item)

    def process_next(self):
        if not self.pending:
            return None
        item = self.pending.popleft()
        self.finished.append(item)
        return item

queue = WorkQueue()
for task in ["read", "validate", "report"]:
    queue.add(task)
while queue.pending:
    print("Processed:", queue.process_next())
assert queue.finished == ["read", "validate", "report"]
assert queue.process_next() is None
print("Undo order:")
while queue.finished:
    print(queue.finished.pop())
assert queue.finished == []

class Node:
    def __init__(self, value):
        self.value = value
        self.left = self.right = None

def insert(root, value):
    if root is None:
        return Node(value)
    if value < root.value:
        root.left = insert(root.left, value)
    elif value > root.value:
        root.right = insert(root.right, value)
    return root

def inorder(root):
    if root:
        yield from inorder(root.left)
        yield root.value
        yield from inorder(root.right)

root = None
for x in [8, 3, 10, 1, 6, 14]:
    root = insert(root, x)

# Run independent scenarios and compare with known answers.

result = list(inorder(None))
print('empty' + ":", result)
assert result == [], "Unexpected result for empty"

result = list(inorder(insert(None, 4)))
print('single' + ":", result)
assert result == [4], "Unexpected result for single"

result = list(inorder(root))
print('existing' + ":", result)
assert result == sorted(result)

print("All scenario checks passed")

def dijkstra(graph, start):
    vertices = set(graph) | {start}
    for edges in graph.values():
        for neighbor, weight in edges:
            if weight < 0:
                raise ValueError("Dijkstra requires nonnegative weights")
            vertices.add(neighbor)
    distance = dict.fromkeys(vertices, float('inf'))
    distance[start] = 0
    remaining = set(vertices)
    while remaining:
        node = min(remaining, key=distance.get)
        if distance[node] == float('inf'):
            break
        remaining.remove(node)
        for neighbor, weight in graph.get(node, []):
            distance[neighbor] = min(distance[neighbor], distance[node] + weight)
    return distance

# Run independent scenarios and compare with known answers.

result = dijkstra({'A':[('B',5),('C',1)],'C':[('B',2)]},'A')
print('weighted' + ":", result)
assert result == {'A': 0, 'C': 1, 'B': 3}, "Unexpected result for weighted"

result = dijkstra({'A':[]},'A')
print('single' + ":", result)
assert result == {'A': 0}, "Unexpected result for single"

print("All scenario checks passed")

