from collections import Counter, deque

def trie_autocomplete(prefix, words):
    """Collect dictionary words under a prefix; sorted suggestions add cost."""
    root = {}
    terminal = None  # Cannot collide with any character key.
    for word in words:
        if not word:
            continue
        node = root
        for char in word:
            node = node.setdefault(char, {})
        node[terminal] = word
    node = root
    for char in prefix:
        if char not in node:
            return []
        node = node[char]
    result = []
    def collect(current):
        if terminal in current:
            result.append(current[terminal])
        for char, child in current.items():
            if char is not terminal:
                collect(child)
    collect(node)
    return sorted(result)

# Run independent scenarios and compare with known answers.

result = trie_autocomplete('ca',['car','cat','dog'])
print('prefix' + ":", result)
assert result == ['car', 'cat'], "Unexpected result for prefix"

result = trie_autocomplete('z',['car','cat'])
print('absent' + ":", result)
assert result == [], "Unexpected result for absent"

result = trie_autocomplete('dog',['dog'])
print('single' + ":", result)
assert result == ['dog'], "Unexpected result for single"

print("All scenario checks passed")

